const body = $input.first().json.body || $input.first().json;
const phone = body.phone || '';
const message = body.message || '';
const pushName = body.pushName || '';
// Normalize phone — remove @s.whatsapp.net suffix
const cleanPhone = phone.split('@')[0];
return {
  phone: cleanPhone,
  rawPhone: phone,
  message: message,
  pushName: pushName
};

