parameters.jsCode:
const raw = $input.first().json;
// DeepSeek returns { choices: [{ message: { content: "..." } }] }
let content = '';
try {
  const parsed = JSON.parse(raw);
  content = parsed.choices?.[0]?.message?.content || '';
} catch { content = ''; }

// Parse the AI response
let action = 'ignore', title = '', priority = 'medium', deadline = null, description = null;
try {
  // Clean markdown fences if any
  content = content.replace(/```json/g, '').replace(/```/g, '').trim();
  const ai = JSON.parse(content);
  action = ai.action || 'ignore';
  title = ai.title || '';
  priority = ai.priority || 'medium';
  deadline = ai.deadline || null;
  description = ai.description || null;
} catch(e) {}

const meta = $('提取消息').first().json;
const phone = meta.phone;
return { action, title, priority, deadline, description, phone };

const createResult = $input.first().json;
let reply = '';
if (createResult.id || createResult.error) {
  if (createResult.error) {
    reply = '创建任务失败';
  } else {
    reply = `✅ 已创建任务 #${createResult.id}: ${createResult.title}`;
    if (createResult.priority === 'high') reply += ' 🔴 高优先级';
    if (createResult.deadline) reply += `\n📅 截止: ${new Date(createResult.deadline).toLocaleDateString('zh-CN')}`;
  }
} else {
  reply = '收到消息，但未检测到任务。';
}

const phone = $('提取消息').first().json.phone;
return { phone, message: reply };
